-- Changelog: Mijn taken per dossier gegroepeerd (feature op main sinds 2026-07-17).
insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-07-17','verbeterd','Taken','Mijn taken per dossier gebundeld',
   'Je taken staan nu per dossier gegroepeerd: elke regel toont het dossiernummer, de omschrijving, of er verlopen taken zijn en hoeveel taken er openstaan. Klap een dossier uit om de taken te zien, of gebruik de knop bovenin om alles in één keer open of dicht te klappen. Klik op een taaknaam om de taak direct te openen en bij te werken.');
